try:
    print('>>> x = bytearray()')
    print('>>> y = 3')
    print('>>> x >>= y')
    print('>>> x')
    x = bytearray()
    y = 3
    x >>= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
